Translate("zhCN", "eastern-plaguelands", {
	title = "东瘟疫之地",
	aliases = { "东部瘟疫之地" },
	sections = {
		{
			title = "概述",
			text = [=[东瘟疫之地是昔日{link:lordaeron}洛丹伦{/link}死去的心脏。亡灵瘟疫最先降临于此，也最为猛烈，至今从未消散。森林灰暗，挂满腐朽。河水流得缓慢而污浊。曾经供养{red:stratholme}斯坦索姆{/red}这座大城的农庄与村落如今空无一人，甚至比空无一人更糟，因为它们的居民仍在道路上游荡，为{link:scourge}天灾军团{/link}效力。没有国王统治这片土地。天灾军团占据着它，{link:scarlet-crusade}血色十字军{/link}从{link:tyr-s-hand}提尔之手{/link}的要塞与之争夺，而{link:argent-dawn}银色黎明{/link}的一小队人在遥远东方的{link:light-s-hope-chapel}圣光之愿礼拜堂{/link}守着一盏孤灯。]=],
		},
		{
			title = "起源",
			text = [=[瘟疫之前，{link:lordaeron}洛丹伦{/link}的东部边境是一片富饶而宁静的乡野。斯坦索姆是王国的第二大城，周围散布着农庄、磨坊和村庄，如{link:darrowshire}达隆郡{/link}、{link:northdale}北谷{/link}和{link:corin-s-crossing}考林路口{/link}。{link:tyr-s-hand}提尔之手{/link}守卫着东{link:southsea-pirates}南海{/link}岸。在北方，越过{link:thondroril-river}索多里尔河{/link}与森林，{link:quel-thalas}奎尔萨拉斯{/link}王国维持着它的边境小屋，在那里狩猎的{link:high-elves}高等精灵{/link}是人们的邻居与朋友。没有史书记载这些村庄中的第一座建于何时。史书记下的，是它们如何终结。]=],
		},
		{
			title = "当今",
			text = [=[这片土地是一个没有前线的战场。{link:cult-of-the-damned}诅咒教派{/link}在{link:corin-s-crossing}考林路口{/link}和{link:plaguewood}病木林{/link}建起黑暗神殿，{link:scourge}天灾军团{/link}在那里建造并缝制新的仆从。瘟疫蝙蝠遮暗天空，瘟疫猎犬在道路上追猎，腐肉蛆虫靠死者养得肥大。{link:scarlet-crusade}血色十字军{/link}占据{link:tyr-s-hand}提尔之手{/link}，派巡逻队北上斯坦索姆，杀死所有不穿其服色的人。与这一切对抗的是{link:light-s-hope-chapel}圣光之愿礼拜堂{/link}，{link:lord-maxwell-tyrosus}玛克斯韦尔·泰罗索斯男爵{/link}和{link:argent-dawn}银色黎明{/link}在那里接纳任何愿意对抗天灾军团的盟友，无论生者还是死者。{link:forsaken}被遗忘者{/link}在这里也有自己的勇士。{link:nathanos-blightcaller}纳萨诺斯·凋零者{/link}守着西南的{link:the-marris-stead}玛瑞斯农场{/link}，同时猎杀天灾军团与生者。在西边河畔的一间小屋里，住着一位曾是白银之手圣骑士的老人，{link:tirion-fordring}提里奥·弗丁{/link}。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:scourge}天灾军团{/link}。{/b}食尸鬼、憎恶、石像鬼和东部村庄复活的死者遍布这片土地。他们通过{link:cult-of-the-damned}诅咒教派{/link}的死灵法师为巫妖王效力。
• {b}{link:scarlet-crusade}血色十字军{/link}。{/b}其骑士和牧师占据着{link:tyr-s-hand}提尔之手{/link}和血色十字军教堂。他们与天灾军团交战，也与其他所有人交战。
• {b}{link:argent-dawn}银色黎明{/link}。{/b}其骑士、学者和军需官从{link:light-s-hope-chapel}圣光之愿礼拜堂{/link}对亡灵进行一场耐心的战争，并奖励任何带来战斗证明的人。
• {b}{link:forsaken}被遗忘者{/link}。{/b}{link:sylvanas-windrunner}女妖之王{/link}的勇士{link:nathanos-blightcaller}纳萨诺斯·凋零者{/link}在{link:the-marris-stead}玛瑞斯农场{/link}进行着他自己的战争。
• {b}{link:quel-lithien-lodge}奎尔林斯{/link}的{link:high-elves}高等精灵{/link}。{/b}在北部边境的一座小屋里，{link:quel-thalas}奎尔萨拉斯{/link}的游侠仍在守望。
• {b}藓刺巨魔。{/b}在废城{link:zul-mashar}祖玛沙尔{/link}，一个{link:trolls}森林巨魔{/link}部族为生存而战。瘟疫已经找上了他们中的一些人。
• {b}不得安息的死者。{/b}鬼魂在{link:darrowshire}达隆郡{/link}和{link:terrordale}恐惧谷{/link}游荡，其中一些仍在等待生者回家。]=],
		},
		{
			title = "历史",
			text = [=[• {b}瘟疫。{/b}{link:cult-of-the-damned}诅咒教派{/link}通过{link:lordaeron}洛丹伦{/link}的谷物散布亡灵瘟疫。东部村庄吃下了谷物，死去，然后又站了起来。
• {b}斯坦索姆的净化。{/b}{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}王子宁可将斯坦索姆屠戮殆尽，也不愿让受污染的居民复活，这座城市在大火中燃烧。在这片土地上，人们把{link:culling-of-stratholme}斯坦索姆的净化{/link}记作东方沦陷的那一天。
• {b}洛丹伦的陷落。{/b}王子以死亡骑士之身从北方归来后，王国陷落了。在{link:fall-of-lordaeron}洛丹伦的陷落{/link}中，东部村庄一个接一个被攻破。在{link:darrowshire}达隆郡{/link}，守军进行了一场坚守，《达隆郡的历史》至今仍铭记着它。
• {b}亡者之战。{/b}{link:scourge}天灾军团{/link}把东方变成了自己的堡垒。{link:scarlet-crusade}血色十字军{/link}从幸存者中崛起，夺取了{link:tyr-s-hand}提尔之手{/link}。{link:argent-dawn}银色黎明{/link}脱离十字军，在{link:light-s-hope-chapel}圣光之愿礼拜堂{/link}找到了自己的家园。当{link:sylvanas-windrunner}女妖之王{/link}前去寻找她的一位老游侠时，{link:forsaken}被遗忘者{/link}也来到了东方。]=],
		},
		{
			title = "瘟疫之地传说",
			text = [=[• {link:light-s-hope-chapel}圣光之愿{/link}的人们说，{link:pamela-redpath}小帕米拉{/link}·{link:marshal-redpath}雷德帕斯{/link}仍在{link:darrowshire}达隆郡{/link}以南的家中等待，在安静的夜晚，能听到她向旅人讨要她的娃娃。
• 经过{link:terrordale}恐惧谷{/link}的人说起那里的一个商人，照他自己的说法，他的价格是疯狂的。他们不确定这个词只是在自夸。
• {link:argent-dawn}银色黎明{/link}用勇气徽记来换取死者身上携带的天灾石。它的军需官们仔细记着数。
• 据说{link:the-marris-stead}玛瑞斯农场{/link}的{link:forsaken}被遗忘者{/link}勇士把每一个前来投奔他的活人仆从都称为蠢货，而这已经是他最客气的说法。]=],
		},
	},
})

Translate("zhCN", "light-s-hope-chapel", {
	title = "圣光之愿礼拜堂",
	aliases = { "圣光之愿" },
	sections = {
		{
			title = "概述",
			text = [=[圣光之愿礼拜堂矗立在瘟疫之地远东的一处绿色{link:razorfen-downs}高地{/link}上，是方圆许多里内唯一一片洁净的土地。它是{link:argent-dawn}银色黎明{/link}的家园。在古老的礼拜堂周围，银色黎明搭起了帐篷、{link:the-cauldron}熔炉{/link}和马厩，{link:sentinels}哨兵{/link}日夜监视着道路。{link:lord-maxwell-tyrosus}玛克斯韦尔·泰罗索斯男爵{/link}在礼拜堂内主持议事。{link:duke-nicholas-zverenhoff}尼古拉斯·瑟伦霍夫公爵{/link}、{link:carlin-redpath}卡林·雷德帕斯{/link}、亡灵骑士{link:leonid-barthalomew}莱尼德·巴萨罗梅{/link}和炼{link:ginro-hearthkindle}金{/link}师{link:betina-bigglezink}贝蒂娜·比格辛克{/link}在礼拜堂的墙下工作。各个种族的旅人都来到这里，因为银色黎明不问它的盟友过去是谁。高地下方有一个坑，银色黎明把死者安放在那里，可即便是这些死者，也难逃窃贼之手。]=],
		},
	},
})

Translate("zhCN", "tyr-s-hand", {
	title = "提尔之手",
	aliases = { "血色十字军教堂" },
	sections = {
		{
			title = "概述",
			text = [=[提尔之手是瘟疫之地东{link:southsea-pirates}南海{/link}岸的一座城墙环绕的城市，也是{link:scarlet-crusade}血色十字军{/link}在东方最大的据点。它的守军听命于{link:high-general-abbendis}莉尼亚·阿比迪斯{/link}，血色十字军教堂耸立在城市中心。每天都有一名信使在提尔之手与北方的十字军指挥部之间往返，每天这座城市都派出士兵与{link:scourge}天灾军团{/link}作战。十字军不信任任何陌生人。不穿十字军服色来到城门前的人都会被砍倒。在十字军手中受苦最深的{link:forsaken}被遗忘者{/link}，密切注视着这座城市。]=],
		},
	},
})

Translate("zhCN", "corin-s-crossing", {
	title = "考林路口",
	aliases = { "考林" },
	sections = {
		{
			title = "概述",
			text = [=[考林路口曾是东部边境中部古老道路交汇处的一座村庄。如今它是{link:cult-of-the-damned}诅咒教派{/link}的巢穴。它的房屋里挤满了邪教徒和复活的死者，聚集在那里的{link:scourge}天灾军团{/link}如此密集，以至于{link:nathanos-blightcaller}纳萨诺斯·凋零者{/link}派他的仆从去那里获取新鲜的腐肉。村庄以西，大地裂开一道深谷。《{link:darrowshire}达隆郡{/link}的历史》记载，黑衣玛杜克的剑断成两截，躺在谷底，而{link:horgus-the-ravager}掠夺者霍古斯{/link}的尸体被扔进了西北方的一座湖中。]=],
		},
	},
})

Translate("zhCN", "darrowshire", {
	title = "达隆郡",
	sections = {
		{
			title = "概述",
			text = [=[达隆郡是东部边境南部丘陵中的一座小村。{link:scourge}天灾军团{/link}到来时，村民没有逃跑。他们在{link:joseph-redpath}约瑟夫·雷德帕斯上尉{/link}的率领下坚守奋战，并在那里死去。《达隆郡的历史》记载，上尉本人在战斗中被腐化，转而攻击自己人。如今村庄已成废墟，死者不得安息。鬼魂在广场上游荡。废墟以南矗立着{link:marshal-redpath}雷德帕斯{/link}家的房子，一个小女孩仍在那里等待父亲从战场归来。]=],
		},
	},
})

Translate("zhCN", "the-marris-stead", {
	title = "玛瑞斯农场",
	aliases = { "玛瑞斯" },
	sections = {
		{
			title = "概述",
			text = [=[玛瑞斯农场是瘟疫之地西南部的一座农场，靠近西部地区的边界。它曾是{link:lordaeron}洛丹伦{/link}游侠领主{link:nathanos-blightcaller}纳萨诺斯·玛瑞斯{/link}的家。{link:scourge}天灾军团{/link}席卷这一地区时，纳萨诺斯在这座农场上坚守阵地，并在这里倒下。他以{link:sylvanas-windrunner}女妖之王{/link}仆从的身份回到了这里。如今他和他的猎犬住在那里，来到农场的活人，要么是为黑暗女王办事的{link:forsaken}被遗忘者{/link}，要么是被派来终结他的{link:alliance}联盟{/link}士兵。田野里散落着头骨。]=],
		},
	},
})

Translate("zhCN", "terrordale", {
	title = "恐惧谷",
	aliases = { "恶蛛隧道" },
	sections = {
		{
			title = "概述",
			text = [=[恐惧谷位于瘟疫之地西北，那里的地势向西部边界倾斜。它曾是一座有旅店和集市的小镇。如今它的街道闹鬼，{link:scourge}天灾军团{/link}的地穴恶魔在连接西部地区的漫长恶蛛隧道中爬行。两个怪人住在废墟中。伊根用他自制的装置猎捕鬼魂。旅人称为“疯子”的{link:augustus-the-touched}奥古斯图斯{/link}，则在等待重新开张他的店铺。]=],
		},
	},
})

Translate("zhCN", "plaguewood", {
	title = "病木林",
	aliases = { "瘟疫要塞" },
	sections = {
		{
			title = "概述",
			text = [=[病木林是西北部一片枯萎的森林，蔓延在{red:stratholme}斯坦索姆{/red}的城墙周围。这是{link:scourge}天灾军团{/link}的工场。通灵塔和屠宰场矗立在枯树之间，天灾军团严密守卫着它们，因为死者从这些建筑中汲取力量，并在其中缝制新的恐怖之物。在林中游荡的食尸鬼和剥皮者，曾是东部村庄的百姓。{link:argent-dawn}银色黎明{/link}雇了一名爆破手来摧毁这些建筑。]=],
		},
	},
})

Translate("zhCN", "zul-mashar", {
	title = "祖玛沙尔",
	aliases = { "玛兹拉罗" },
	sections = {
		{
			title = "概述",
			text = [=[祖玛沙尔是瘟疫之地东北尽头的一座{link:trolls}巨魔{/link}废城，靠近{link:quel-thalas}奎尔萨拉斯{/link}的边界。藓刺巨魔在督军瑟{link:farmer-ray}雷{/link}什{link:ginro-hearthkindle}金{/link}和巫医祖布林·扭枝的统领下占据着它。瘟疫也找上了他们。他们的一些斥候在回家的路上吃了受污染的肉，如今一个巫妖的声音驱使他们把疾病带给自己的族人。城市西南方是更古老的玛兹拉罗遗迹。]=],
		},
	},
})

Translate("zhCN", "the-noxious-glade", {
	title = "剧毒林地",
	sections = {
		{
			title = "概述",
			text = [=[剧毒林地是瘟疫之地东北部一座被毒化的{link:stranglethorn-vale}山谷{/link}，位于{link:light-s-hope-chapel}圣光之愿{/link}以北。这里的空气浓稠而发绿，活体腐烂形成的软泥怪在洼地中爬行。{link:scourge}天灾军团{/link}把它的勇士驻扎在这里，{link:cult-of-the-damned}诅咒教派{/link}在林间举行黑暗仪式。在{link:moonglade}林地{/link}中行走的一些勇士曾参加过{link:darrowshire}达隆郡{/link}之战，他们的头骨里至今回荡着那段记忆。]=],
		},
	},
})

Translate("zhCN", "thondroril-river", {
	title = "索多里尔河",
	aliases = { "索多里尔" },
	sections = {
		{
			title = "概述",
			text = [=[索多里尔河是分隔东{link:western-plaguelands}西瘟疫之地{/link}的河流。它的河水幽暗而迟缓，很少有旅人在岸边逗留。然而在东岸，隐藏在树林间，有一间小屋，屋旁有一根钓线和一堆做饭的火。一位老人和他的马米拉多尔独自住在那里。他的名字是{link:tirion-fordring}提里奥·弗丁{/link}。他曾是一位领主，也是白银之手的圣骑士，却为了一个{link:orcs}兽人{/link}失去了这两个头衔。他只请求客人帮他对付猎犬和蝙蝠，作为回报，他会提供一顿热饭和他一生的故事。]=],
		},
	},
})

Translate("zhCN", "crown-guard-tower", {
	title = "皇冠哨塔",
	sections = {
		{
			title = "概述",
			text = [=[皇冠哨塔是{link:lordaeron}洛丹伦{/link}的一座古老瞭望塔，位于南路上，在{link:darrowshire}达隆郡{/link}与{link:the-marris-stead}玛瑞斯农场{/link}之间。它当年是为守卫国王在东方的道路而建。国王已死，道路已归{link:scourge}天灾军团{/link}所有，但塔依然矗立，像一根孤零零的石指耸立在枯萎之上。生者的士兵有时在塔中避难。他们没有一个久留。]=],
		},
	},
})

Translate("zhCN", "quel-lithien-lodge", {
	title = "奎尔林斯小屋",
	aliases = { "奎尔林斯" },
	sections = {
		{
			title = "概述",
			text = [=[奎尔林斯小屋是{link:high-elves}高等精灵{/link}在瘟疫之地北部边境的一座狩猎小屋，靠近通往{link:quel-thalas}奎尔萨拉斯{/link}的道路。游侠、林居者和探路者在{link:ranger-lord-hawkspear}死亡猎人霍克斯比尔{/link}的统领下在此守望。小屋还保存着往昔的记录，那时高等精灵训练{link:lordaeron}洛丹伦{/link}的游侠。其中有一本《奎尔萨拉斯名册》，记载着{link:nathanos-blightcaller}纳萨诺斯·玛瑞斯{/link}作为凡人的生平。凋零者想要拿回它，至于有多少精灵必须为此受苦，他毫不在乎。]=],
		},
	},
})

Translate("zhCN", "the-undercroft", {
	title = "墓室",
	sections = {
		{
			title = "概述",
			text = [=[墓室是瘟疫之地西南部的一座古老地穴，位于{link:the-marris-stead}玛瑞斯农场{/link}以南。它曾是东部村庄死者的安息之所。在它的坟墓中有一座假墓。当{link:tirion-fordring}提里奥·弗丁{/link}被放逐时，他的儿子被告知父亲已死，这个男孩被带到这里来哀悼。如今这座地穴是死亡{link:trolls}巨魔{/link}窃贼的藏身之处，他们由{link:zaeldarr-the-outcast}流亡者塞达尔{/link}率领，夜里偷偷出去，从{link:light-s-hope-chapel}圣光之愿{/link}的坑中偷走尸体。在地穴后面一辆旧马车旁，一个藓刺巨魔在瘟疫夺走他的神智之前埋下了一只箱子。]=],
		},
	},
})

Translate("zhCN", "northdale", {
