			title = "概述",
			text = [=[北谷曾是瘟疫之地东北部的一座小村，位于{link:light-s-hope-chapel}圣光之愿{/link}以外。白银之手瓦解之时，年轻的圣骑士{link:taelan-fordring}泰兰·弗丁{/link}在北谷进行了最后的抵抗，并在那里扔下了骑士团的旗帜。那面旗帜至今仍躺在废墟之中。在小村以西的北方荒原上，游荡着巨大的蛆虫{link:borelgore}淤血虫{/link}，它曾整队整队地吞下士兵。]=],
		},
	},
})

Translate("zhCN", "the-fungal-vale", {
