})

Translate("zhCN", "nathanos-blightcaller", {
	title = "纳萨诺斯·凋零者",
	subtitle = "女妖之王的勇士",
	found = "玛瑞斯农场，在瘟疫之地西南部",
	hint = "寻找在西南方守着一座满是头骨与猎犬之农场的被遗忘者游侠。",
	allegiance = "被遗忘者 · 希尔瓦娜斯·风行者",
	aliases = { "纳萨诺斯", "纳萨诺斯·玛瑞斯", "凋零者" },
	sections = {
		{
			title = "概述",
			text = [=[纳萨诺斯·凋零者是{link:forsaken}被遗忘者{/link}在{link:eastern-plaguelands}东瘟疫之地{/link}的勇士。生前他是纳萨诺斯·玛瑞斯，{link:lordaeron}洛丹伦{/link}的一位游侠领主，也是唯一一个获准在{link:quel-thalas}奎尔萨拉斯{/link}游侠中受训的{link:humans}人类{/link}。他在自己的农场上倒在{link:scourge}天灾军团{/link}手下，复活为它的奴隶。{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}解放了他。如今他带着他的凋零猎犬守着{link:the-marris-stead}玛瑞斯农场{/link}，以同样冰冷的仇恨猎杀天灾军团和生者。他对效力于他的人十分残忍，除了黑暗女王，他谁也不信任。]=],
		},
		{
			title = "意义",
			text = [=[纳萨诺斯同时具有两种身份，战争双方都知道这一点。对{link:alliance}联盟{/link}来说，他曾是英雄。他的本领在十年战争中赢得过胜利，再没有别的{link:humans}人类{/link}升到游侠领主之位。对{link:forsaken}被遗忘者{/link}来说，他是{link:sylvanas-windrunner}女妖之王{/link}的勇士中第一个、也是最令人畏惧的一个。他的命运是联盟的一道伤口。{link:stormwind-city}暴风城{/link}的摄政王得知此事后，派出一支军队去终结他。]=],
		},
		{
			title = "生与死",
			text = [=[纳萨诺斯生为{link:lordaeron}洛丹伦{/link}的{link:humans}人类{/link}。{link:high-elves}高等精灵{/link}把他收入他们的游侠组织，这是他们从未为他的种族中任何其他人做过的事，而他升到了其中的最高阶位。{link:scourge}天灾军团{/link}席卷东部边境时，他在自己的农场上坚守阵地，保卫王国。一大波死者将他淹没。他看到的最后一样东西，是一个盘旋在他上方的憎恶，内脏从它的胸口垂下。他醒来时已是天灾军团的一员，心智被束缚于巫妖王。他在很长时间里无能为力。后来，{link:sylvanas-windrunner}女妖之王{/link}来找他了，就像他不知怎地早已知道她会来那样，她打碎了他的锁链。]=],
		},
		{
			title = "事迹",
			text = [=[• 获得自由后，他在荒原上追猎憎恶拉姆斯登长达数月，直到它逃进斯坦索姆。
• 他训练{link:sylvanas-windrunner}黑暗女王{/link}派给他的{link:forsaken}被遗忘者{/link}，带着轻蔑，毫不留情。
• 他杀死了{link:stormwind-city}暴风城{/link}派来查明凋零者身份的{link:si-7}军情七处{/link}特工。
• 他奉{link:varimathras}瓦里玛萨斯{/link}之命策划对付{link:scarlet-crusade}血色十字军{/link}。]=],
		},
		{
			title = "当今",
			text = [=[纳萨诺斯独自和他的猎犬守着{link:the-marris-stead}玛瑞斯农场{/link}。他派仆从去{link:corin-s-crossing}考林路口{/link}取腐肉喂猎犬，清除他天空中的瘟疫蝙蝠，并猎杀北方的怪物。在他的训练中幸存下来的{link:forsaken}被遗忘者{/link}会在他的勇士中赢得一席之地。来到农场的{link:alliance}联盟{/link}士兵通常不会离开。]=],
		},
	},
	chapters = {
		{
			title = "女妖之王的勇士",
			hint = "响应黑暗女王的召唤，前往玛瑞斯农场报到。",
			text = [=[{link:sylvanas-windrunner}女妖之王{/link}把她最老练的仆从派往东方的{link:the-marris-stead}玛瑞斯农场{/link}。纳萨诺斯以轻蔑迎接他们。他以为他们是来喂他的猎犬的，因为他想不出他们来打扰他还会有别的理由。]=],
		},
		{
			title = "有目的的杀戮",
			hint = "在玛瑞斯农场证明你的价值。",
			text = [=[纳萨诺斯的第一课是跑腿。他的仆从把刚被杀死的{link:scourge}天灾军团{/link}的腐肉磨成猎犬的饲料，并猎杀每当他离开农场时就来骚扰他的瘟疫蝙蝠。他称之为训练。他还说，他有比杀蝙蝠更重要的事要做，而他的仆从没有。]=],
		},
		{
			title = "游侠领主的命令",
			hint = "从北方的精灵那里取回一份记载凋零者凡人生平的记录。",
			text = [=[在{link:quel-lithien-lodge}奎尔林斯小屋{/link}，{link:high-elves}高等精灵{/link}保存着一本记载他凡人生平的名册。纳萨诺斯想要拿回它，还想让保管它的精灵受苦。他没有说为什么。他只警告说，他的仆从谁也别蠢到去读它。]=],
		},
		{
			title = "拉姆斯登",
			hint = "为凋零者之死复仇。",
			text = [=[在纳萨诺斯临死时盘旋在他上方的，正是憎恶拉姆斯登。{link:sylvanas-windrunner}希尔瓦娜斯{/link}解放他之后，他追猎了它数月，直到它逃进斯坦索姆。当它的头颅被带到他面前时，他大声地想，它是否求过饶，它是否根本懂得什么是怜悯。他发誓要把这颗头挂在他的墙上。]=],
		},
		{
			title = "血色先知",
			hint = "执行凋零者对血色十字军的计谋。",
			text = [=[{link:varimathras}瓦里玛萨斯{/link}传话说，必须打击{link:scarlet-crusade}血色十字军{/link}的大十字军。纳萨诺斯在十字军每日往来的信使身上找到了弱点。他改写了大十字军的命令，派一名伪装成十字军的仆从进入{link:tyr-s-hand}提尔之手{/link}。命令要求把大十字军的首席顾问、{link:demetria}血色先知{/link}德米提雅送往北方的斯坦索姆。十字军照办了。纳萨诺斯已在路上等候。]=],
		},
		{
			title = "凋零者的真面目",
			hint = "替暴风城查明凋零者是谁。",
			text = [=[三名{link:si-7}军情七处{/link}的特工进入{link:eastern-plaguelands}东瘟疫之地{/link}去查明凋零者是谁，没有一个回来。人们在{link:the-marris-stead}玛瑞斯农场{/link}附近找到了他们的徽记。真相大白时，认识纳萨诺斯·玛瑞斯的人们心碎了。{link:stormwind-city}暴风城{/link}的摄政王无法相信那位游侠领主竟成了{link:sylvanas-windrunner}女妖之王{/link}的勇士，他下令派一支军队去终结他。]=],
		},
	},
	mentions = {
		{ text = "{link:sylvanas-windrunner}女妖之王{/link}的勇士" },
		{ text = "有目的的杀戮" },
		{ text = "亡者生活中的小烦恼" },
		{ text = "游侠领主的命令" },
		{ text = "暮翼，我是多么恨你……" },
		{ text = "{link:borelgore}肥胖者{/link}" },
		{ text = "拉姆斯登" },
		{ text = "指挥的召唤" },
		{ text = "血色信使" },
		{ text = "纳萨诺斯的计谋" },
		{ text = "回到纳萨诺斯那里" },
		{ text = "{link:demetria}血色先知{/link}德米提雅" },
		{ text = "东部瘟疫" },
		{ text = "凋零者来了" },
		{ text = "必须恢复秩序" },
	},
	bonds = {
		{ id = "sylvanas-windrunner", name = "希尔瓦娜斯·风行者", note = "把他从巫妖王手中解放出来" },
		{ id = "varimathras", name = "瓦里玛萨斯", note = "从幽暗城给他下达命令" },
		{ id = "bolvar-fordragon", name = "伯瓦尔·弗塔根", note = "要求处死他" },
		{ id = "ranger-lord-hawkspear", name = "死亡猎人霍克斯比尔", note = "保管着他凡人生平的名册" },
		{ id = "duskwing", name = "暗翼蝠", note = "他憎恨的蝙蝠" },
		{ id = "borelgore", name = "淤血虫", note = "令他损失了整团整团的兵力" },
		{ id = "demetria", name = "德米提雅", note = "他追猎的先知" },
	},
})

Translate("zhCN", "lord-maxwell-tyrosus", {
	title = "玛克斯韦尔·泰罗索斯男爵",
	subtitle = "银色黎明的领袖",
	found = "圣光之愿礼拜堂内",
	hint = "寻找在圣光之愿礼拜堂内主持议事的领主。",
	allegiance = "银色黎明",
	aliases = { "玛克斯韦尔·泰罗索斯", "泰罗索斯", "玛克斯韦尔领主" },
	sections = {
		{
			title = "概述",
			text = [=[玛克斯韦尔·泰罗索斯男爵在{link:light-s-hope-chapel}圣光之愿{/link}的礼拜堂内领导{link:argent-dawn}银色黎明{/link}。他曾属于{link:scarlet-crusade}血色十字军{/link}。当他看清十字军的狂热将把它引向何方时，他拒绝追随，并帮助建立了一个对抗{link:scourge}天灾军团{/link}、却不仇视其他所有人的组织。他很少离开礼拜堂，多年来从未接见过外人。那些被带到他面前的人，都是挣得了这份殊荣的。]=],
		},
		{
			title = "意义",
			text = [=[泰罗索斯是{link:argent-dawn}银色黎明{/link}这场伟大试验的核心：一个不问任何人曾效力于哪个种族或哪面旗帜、只问他们是否愿意对抗死者的组织。聚集在他身边的有一名亡灵骑士、一位{link:gnomes}侏儒{/link}炼{link:ginro-hearthkindle}金{/link}师、一位贵族语言学家和一个{link:darrowshire}达隆郡{/link}的伤心之子。他们能够共事，全靠他。]=],
		},
		{
			title = "事迹",
			text = [=[• 他离开{link:scarlet-crusade}血色十字军{/link}，帮助建立了{link:argent-dawn}银色黎明{/link}。
• 他从{link:light-s-hope-chapel}圣光之愿礼拜堂{/link}领导银色黎明对{link:scourge}天灾军团{/link}的战争。
• 他掌管着已经锁闭多年的银色黎明宝库。]=],
		},
		{
			title = "未载",
			text = [=[史书很少提及泰罗索斯在加入十字军之前的生平，也未提及他头衔背后的领地。本条目只记录他在{link:argent-dawn}银色黎明{/link}中的地位。]=],
		},
	},
	chapters = {
		{
			title = "觐见玛克斯韦尔领主",
			hint = "证明自己是银色黎明的勇士，并被引见给它的领袖。",
			text = [=[{link:duke-nicholas-zverenhoff}尼古拉斯·瑟伦霍夫公爵{/link}把这位勇士带到玛克斯韦尔领主本人面前，这是{link:argent-dawn}银色黎明{/link}多年来未曾给予任何外人的荣誉。泰罗索斯把这位新来者当作值得信赖的盟友来接待。多年来第一次，银色黎明宝库向组织之外的人敞开了。]=],
		},
	},
	mentions = {
		{ text = "玛克斯韦尔·泰罗索斯男爵" },
		{ text = "{link:argent-dawn}银色黎明{/link}宝库" },
	},
	bonds = {
		{ id = "duke-nicholas-zverenhoff", name = "尼古拉斯·瑟伦霍夫公爵", note = "为他引荐勇士" },
		{ id = "leonid-barthalomew", name = "莱尼德·巴萨罗梅", note = "他组织中的一名亡灵骑士" },
		{ id = "carlin-redpath", name = "卡林·雷德帕斯", note = "银色黎明的一位兄弟" },
	},
})

Translate("zhCN", "duke-nicholas-zverenhoff", {
	title = "尼古拉斯·瑟伦霍夫公爵",
	subtitle = "银色黎明的公爵",
	found = "圣光之愿礼拜堂，礼拜堂墙下",
	hint = "与在圣光之愿发放银色黎明委任状的公爵交谈。",
	allegiance = "银色黎明",
	aliases = { "瑟伦霍夫", "尼古拉斯·瑟伦霍夫", "公爵" },
	sections = {
		{
			title = "概述",
			text = [=[尼古拉斯·瑟伦霍夫公爵是{link:argent-dawn}银色黎明{/link}最受尊敬的领袖之一。他是一位博学的贵族，在整个组织中以杰出的语言学家闻名。在{link:light-s-hope-chapel}圣光之愿{/link}，他把银色黎明的委任状发给所有愿意为之而战的人，并为从死者身上取得的每一块天灾石付钱。他对盟友彬彬有礼，对{link:scourge}天灾军团{/link}和{link:scarlet-crusade}血色十字军{/link}的狂热者则毫不留情。]=],
		},
		{
			title = "意义",
			text = [=[公爵是{link:argent-dawn}银色黎明{/link}的招募者，也是勇士的评判者。他相信任何走向极端的事物都是对世界的威胁，而他把十字军的盲目狂热也算在这些威胁之中。他教导说，银色黎明必须宽容，却又对自己的信念毫不动摇。他认为值得的人，会被他引见给{link:lord-maxwell-tyrosus}玛克斯韦尔·泰罗索斯男爵{/link}。]=],
		},
		{
			title = "事迹",
			text = [=[• 他颁发{link:argent-dawn}银色黎明{/link}的委任状，持有者可以从倒下的敌人身上收集天灾石。
• 他用天灾石兑换银色黎明的勇气徽记。
• 他研究送到银色黎明的奇异文字，比如一位来自{link:winterspring}冬泉谷{/link}的通灵者的书。
• 他派勇士进入斯坦索姆，同时对抗十字军和{link:scourge}天灾军团{/link}。]=],
		},
		{
			title = "未载",
			text = [=[没有史书记载公爵在瘟疫之前的领地位于何处，也没有记载他是如何加入{link:argent-dawn}银色黎明{/link}的。]=],
		},
	},
	chapters = {
		{
			title = "银色黎明的委任状",
			hint = "在圣光之愿接受银色黎明的委任状。",
			text = [=[每一个以{link:argent-dawn}银色黎明{/link}之名与{link:scourge}天灾军团{/link}作战的士兵都带着它的委任状。公爵解释说，有了它，持有者便可以拿走死者有时携带的天灾石，那是它们的阶级标记。公爵为每一组天灾石付钱，而对天灾军团首领的石头，他出价最高。]=],
		},
